def parse_sensor_reading(sensor_string):
    '''
    Create a function called parse_sensor_reading that takes a string like 'T:25.5|H:60|TS:1234567890'. Split by '|' to get parts. For each part, split by ':' to get key and value. Return dict with 'temperature', 'humidity', 'timestamp' keys. If a value cannot be converted to float/int, set to None. Handle T as float, H as float, TS as int.
    '''
    result = {
        'temperature': None,
        'humidity': None,
        'timestamp': None
    }
    mapping = {
        'T': ('temperature', float),
        'H': ('humidity', float),
        'TS': ('timestamp', int)
    }

    # If the input is empty or None, just return result
    if not sensor_string or not isinstance(sensor_string, str):
        return result

    parts = sensor_string.split('|')
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if ':' not in part:
            continue
        key, value = part.split(':', 1)
        if key in mapping:
            result_key, conv_type = mapping[key]
            try:
                result[result_key] = conv_type(value)
            except (ValueError, TypeError):
                result[result_key] = None
    return result

